apiVersion: v1
kind: ConfigMap
metadata:
  name: iris-ui-nginx-config
data:
  default.conf: |
    server {
      listen 3000;
      server_name localhost;
      root /usr/share/nginx/html;
      index index.html;

      include /etc/nginx/mime.types;
      default_type application/octet-stream;
      types {
        application/javascript js mjs;
      }

      # Security headers
      add_header X-Frame-Options "SAMEORIGIN" always;
      add_header X-Content-Type-Options "nosniff" always;
      add_header X-XSS-Protection "1; mode=block" always;
      add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

      server_tokens off;

      gzip on;
      gzip_vary on;
      gzip_min_length 1024;
      gzip_proxied any;
      gzip_types text/plain text/css text/xml text/javascript application/javascript application/json application/xml+rss application/atom+xml image/svg+xml;

      location / {
        try_files $uri /index.html;
      }

      location /health {
        access_log off;
        return 200 '{"status":"healthy"}';
        add_header Content-Type text/plain;
        add_header X-Content-Type-Options "nosniff" always;
      }

      location /api/ {
        proxy_pass http://iris-api:5000/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port $server_port;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 90;
      }

      location /auth/ {
        proxy_pass http://iris-keycloak:8080/auth/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port $server_port;
        proxy_buffer_size 128k;
        proxy_buffers 4 256k;
        proxy_busy_buffers_size 256k;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 90;
      }
    }

resource "aws_launch_template" "runner" {
  name_prefix   = "${var.project_name}-"
  image_id      = local.ami_id
  instance_type = var.instance_type

  iam_instance_profile {
    arn = aws_iam_instance_profile.runner.arn
  }

  vpc_security_group_ids = [aws_security_group.runner.id]

  # Root volume - OS + workspace
  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size           = var.runner_disk_size_gb
      volume_type           = "gp3"
      iops                  = 3000
      throughput            = 250
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required" # IMDSv2 enforced
    http_put_response_hop_limit = 2
  }

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "${var.project_name}-ephemeral"
      Role = "github-runner"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      Name = "${var.project_name}-root"
    })
  }

  user_data = base64encode(templatefile("${path.module}/scripts/runner-bootstrap.sh", {
    aws_region            = var.aws_region
    github_pat_secret_arn = var.github_pat_secret_arn
    github_org            = var.github_org
    github_repo           = var.github_repo
    runner_labels         = var.runner_labels
    efs_filesystem_id     = aws_efs_file_system.cache.id
    project_name          = var.project_name
  }))

  update_default_version = true

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

