resource "aws_iam_role_policy" "runner_self_terminate" {
  name = "self-terminate"
  role = aws_iam_role.runner.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SelfTerminate"
        Effect   = "Allow"
        Action   = "ec2:TerminateInstances"
        Resource = "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:instance/*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/Project" = var.project_name
          }
        }
      },
      {
        Sid    = "DescribeInstances"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "runner_secrets" {
  name = "secrets-access"
  role = aws_iam_role.runner.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadGitHubPAT"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = var.github_pat_secret_arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "runner_efs_cache" {
  name = "efs-cache-access"
  role = aws_iam_role.runner.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EFSMountAndReadWrite"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:DescribeMountTargets",
          "elasticfilesystem:DescribeFileSystems"
        ]
        Resource = aws_efs_file_system.cache.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "runner_ecr" {
