        Sid    = "ECRAuth"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRPushPull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload"
        ]
        Resource = "arn:${local.partition}:ecr:${var.aws_region}:${local.account_id}:repository/*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "runner_cloudwatch_logs" {
  name = "cloudwatch-logs"
  role = aws_iam_role.runner.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${local.partition}:logs:${var.aws_region}:${local.account_id}:log-group:/github-runner/*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_ec2" {
  name = "ec2-launch"
  role = aws_iam_role.lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LaunchRunner"
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:CreateTags"
        ]
        Resource = [
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:launch-template/*",
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:instance/*",
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:volume/*",
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:network-interface/*",
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:security-group/*",
          "arn:${local.partition}:ec2:${var.aws_region}:${local.account_id}:subnet/*",
          "arn:${local.partition}:ec2:${var.aws_region}::image/*"
        ]
      },
      {
        Sid    = "LaunchTemplateAccess"
        Effect = "Allow"
        Action = [
          "ec2:DescribeLaunchTemplateVersions"
        ]
        Resource = "*"
      },
      {
        Sid      = "PassRoleToRunner"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.runner.arn
      }
    ]
  })
}

resource "aws_launch_template" "runner" {
  name_prefix   = "${var.project_name}-"
  image_id      = local.ami_id
  instance_type = var.instance_type

  iam_instance_profile {
    arn = aws_iam_instance_profile.runner.arn
  }

  vpc_security_group_ids = [aws_security_group.runner.id]

  # Root volume - OS + workspace
  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size           = var.runner_disk_size_gb
      volume_type           = "gp3"
      iops                  = 3000
      throughput            = 250
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required" # IMDSv2 enforced
    http_put_response_hop_limit = 2
  }

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "${var.project_name}-ephemeral"
      Role = "github-runner"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      Name = "${var.project_name}-root"
    })
  }

  user_data = base64encode(templatefile("${path.module}/scripts/runner-bootstrap.sh", {
    aws_region            = var.aws_region
    github_pat_secret_arn = var.github_pat_secret_arn
    github_org            = var.github_org
    github_repo           = var.github_repo
    runner_labels         = var.runner_labels
    efs_filesystem_id     = aws_efs_file_system.cache.id
    project_name          = var.project_name
  }))

  update_default_version = true

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lambda_function" "webhook" {
  function_name    = "${var.project_name}-webhook-handler"
  handler          = "webhook-handler.lambda_handler"
  runtime          = "python3.12"
