resource "aws_security_group" "runner" {
  name_prefix = "${var.project_name}-runner-"
  description = "Security group for ephemeral GitHub runners"
  vpc_id      = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-runner-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_efs_file_system" "cache" {
  creation_token  = "${var.project_name}-cache"
  encrypted       = true
  throughput_mode = var.efs_throughput_mode

  lifecycle_policy {
    transition_to_ia = var.efs_transition_to_ia_days
  }

  lifecycle_policy {
    transition_to_primary_storage_class = "AFTER_1_ACCESS"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache"
    Role = "persistent-cache"
  })
}
